import backtrader as bt


class CCISlopeMeanReversionStrategy(bt.Strategy):
    params = (
        ("cci_period", 20),
        ("slope_period", 20),
        ("statistics_period", 20),
        ("entry_zscore", 2.0),
        ("stop_loss_fraction", 0.02),
    )

    def __init__(self):
        self.cci = bt.indicators.CommodityChannelIndex(
            self.data,
            period=self.p.cci_period,
        )
        self.cci_slope = bt.indicators.LinearRegressionSlope(
            self.cci,
            period=self.p.slope_period,
        )
        self.mean_slope = bt.indicators.SMA(
            self.cci_slope,
            period=self.p.statistics_period,
        )
        self.std_slope = bt.indicators.StdDev(
            self.cci_slope,
            period=self.p.statistics_period,
        )

        self.order = None
        self.stop_order = None

    def next(self):
        if self.order is not None:
            return

        slope = self.cci_slope[0]
        mean_slope = self.mean_slope[0]

        if not self.position:
            std_slope = self.std_slope[0]
            if std_slope == 0:
                return

            z = (slope - mean_slope) / std_slope
            if z > self.p.entry_zscore:
                self.order = self.buy()
            elif z < -self.p.entry_zscore:
                self.order = self.sell()
        elif self.position.size > 0 and slope <= mean_slope:
            if self.stop_order is not None:
                self.cancel(self.stop_order)
            self.order = self.close()
        elif self.position.size < 0 and slope >= mean_slope:
            if self.stop_order is not None:
                self.cancel(self.stop_order)
            self.order = self.close()

    def notify_order(self, order):
        if order.status not in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            return

        if order is self.stop_order:
            self.stop_order = None
            return

        if order is self.order:
            self.order = None
            if order.status == order.Completed and self.position:
                entry_price = order.executed.price
                if self.position.size > 0:
                    self.stop_order = self.sell(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=entry_price * (1.0 - self.p.stop_loss_fraction),
                    )
                else:
                    self.stop_order = self.buy(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=entry_price * (1.0 + self.p.stop_loss_fraction),
                    )
